T = [['doodh', 'double roti', 'anday'], ['doodh', 'chai patti'], ['doodh', 'double roti', 'chai patti', 'cheeni'], ['double roti', 'anday'], ['doodh', 'double roti', 'chai patti']] 
def support(transactions, itemset): 
    count = 0 
    for t in transactions: 
        found = True 
        for item in itemset: 
            if item not in t: 
                found = False 
        if found == True: 
            count = count + 1 
    return round(count / len(transactions), 2) 
def rule_metrics(transactions, lhs, rhs): 
    full_set = lhs + rhs 
    supp_lhs = support(transactions, lhs) 
    supp_full = support(transactions, full_set) 
    supp_rhs = support(transactions, rhs) 
    if supp_lhs == 0: 
        return (round(supp_full, 2), 0.0, 0.0) 
    conf = supp_full / supp_lhs 
    lift = conf / supp_rhs 
    return (round(supp_full, 2), round(conf, 2), round(lift, 2)) 
print(rule_metrics(T, ['doodh'], ['double roti']))

